package com.bank.customer.service;

import com.bank.customer.dto.AccountSummaryDto;
import jakarta.persistence.EntityManager;
import jakarta.persistence.PersistenceContext;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Slf4j
public class CustomerService {

    @PersistenceContext
    private EntityManager em;

    // CORRECT: fetch everything the view needs INSIDE the transaction, as a DTO.
    // No lazy association is touched during JSON rendering → OSIV not needed.
    @Transactional(readOnly = true)
    public AccountSummaryDto getSummary(String id) {
        AccountSummaryDto dto = em.createQuery(
                "select new com.bank.customer.dto.AccountSummaryDto(" +
                "  a.id, a.holderName, a.balance, count(t)) " +
                "from Account a left join a.transactions t " +
                "where a.id = :id group by a.id, a.holderName, a.balance",
                AccountSummaryDto.class)
                .setParameter("id", id)
                .getSingleResult();
        log.info("Loaded summary for {} inside TX; view sees only the DTO", id);
        return dto;  // detached DTO — serialization touches nothing lazy
    }
}
