package com.bank.customer.controller;

import com.bank.customer.dto.AccountSummaryDto;
import com.bank.customer.service.CustomerService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1/customers")
@RequiredArgsConstructor
public class CustomerController {

    private final CustomerService customerService;

    @GetMapping("/{id}/summary")
    public AccountSummaryDto summary(@PathVariable String id) {
        // Returns a DTO. With OSIV off, no lazy load happens here → no N+1, no exception.
        return customerService.getSummary(id);
    }
}
